"""Separable equations, solution branches and verification."""
def make_unit(page,ex,summary):
 return ('Aðskiljanlegar deildajöfnur',[
 page('Breytur aðskildar','Þekkja formið g(y)y′ = f(x) og tengja það við keðjuregluna.',r'''<p>Í aðskiljanlegri deildajöfnu má safna því sem fer eftir y öðrum megin og því sem fer eftir x hinum megin. Byrjum á jöfnu sem er þegar á hentugu formi:</p>\[y\,y'=x.\]<p>Hér merkir y′ afleiðu y með tilliti til x. Keðjureglan gefur:</p>\[\left(\frac{y^2}{2}\right)'=y\,y'.\]<p>Við getum því heildað báðar hliðar:</p>\[\frac{y^2}{2}=\frac{x^2}{2}+C.\]<p>Við höfum fundið samband milli x og y. Næstu skref eru að nota skilyrði ef það er gefið og athuga hvaða fall y sambandið lýsir.</p><h2>Almenna hugmyndin</h2>\[g(y)y'=f(x).\]<p>Ef G er stofnfall g gefur keðjureglan:</p>\[(G(y(x)))'=g(y)y'.\]<p>Því má skrifa niðurstöðuna:</p>\[\int g(y)\,dy=\int f(x)\,dx.\]<p>Við heildum vinstri hlið með tilliti til y og hægri hlið með tilliti til x. Einn frjáls fasti nægir þegar stofnföllin eru sett jöfn hvort öðru.</p><aside>Táknunin g(y) dy=f(x) dx er hentug leið til að halda utan um breyturnar. Réttlæting skrefsins kemur frá keðjureglunni, eins og í dæminu hér að ofan.</aside>''',[
 ex(r'Finndu samband milli x og y með því að heilda \(2y\,y\prime=6x\) og gefðu samband milli x og y.','Hvaða fall af y hefur afleiðuna 2y með tilliti til y?','Heildi 2y með tilliti til y er y².',r'\(y^2=3x^2+C\). Diffrun gefur 2yy′=6x.','#s1'),
 ex(r'Finndu samband milli x og y með því að heilda \((1+y^2)y\prime=2x\).','Vinstra megin er heildað með tilliti til y.','Heilda 1+y² lið fyrir lið.',r'\(y+\frac{y^3}{3}=x^2+C\). Diffrun sambandsins gefur (1+y²)y′=2x.','#s1'),
 ex(r'Af hverju er \((y^2)\prime=2y\,y\prime\), en ekki bara 2y, þegar diffrað er með tilliti til x?','Mundu að y er fall af x.','Beittu keðjureglunni á y(x)².','Ytra fallið er veldisfall og innra fallið er y(x). Afleiða innra fallsins er y′ og þarf því að fylgja.','#s1')]),
 page('Frá margfeldi að aðskildu formi','Aðskilja breytur, heilda og halda utan um fastalausnir.',r'''<p>Önnur algeng framsetning er:</p>\[y'=p(x)q(y).\]<p>Þar sem q(y)≠0 deilum við með q(y):</p>\[\frac{y'}{q(y)}=p(x).\]\[\int\frac1{q(y)}\,dy=\int p(x)\,dx.\]<p><strong>Áður en deilt er þarf að athuga núllstöðvar q.</strong> Ef q(b)=0 er fastafallið y=b lausn upphaflegu jöfnunnar. Slík lausn er ekki tekin með í deilingarskrefinu.</p><h3>Sýnidæmi 12.2.1</h3>\[y'=2xy.\]<p>Núllfallið y=0 er lausn. Fyrir y≠0 aðskiljum við:</p>\[\frac{y'}y=2x.\]\[\int\frac1y\,dy=\int2x\,dx.\]\[\ln|y|=x^2+C.\]<p>Með því að taka veldisfall af báðum hliðum fæst:</p>\[|y|=e^Ce^{x^2}.\]<p>Þar sem eᶜ&gt;0 má sameina formerkið og stuðulinn í nýjan fasta A≠0:</p>\[y=Ae^{x^2}.\]<p>Við bætum núlllausninni við með því að leyfa einnig A=0. Allar lausnir eru þá:</p>\[y=Ae^{x^2},\qquad A\in\mathbb R.\]<p>Athugun: y′=2xAeˣ²=2xy, líka þegar A=0.</p><h2>Er hægt að aðskilja breyturnar?</h2><p>Margfeldið xy skiptist í þátt sem fer eftir x og þátt sem fer eftir y. Summan x+y skiptist ekki þannig. Það að y komi fyrir hægra megin gerir jöfnu því ekki sjálfkrafa aðskiljanlega.</p>'''+choice_widget(),[
 ex(r'Finndu almenna lausn \(y\prime=3x^2y\). Taktu núlllausnina með.','Fyrir y≠0 má deila með y og heilda.','ln|y|=x³+C.',r'\(y=Ae^{x^3}\), fyrir allar rauntölur A. Afleiðan er 3x²y. A=0 gefur núlllausnina.','#s2'),
 ex(r'Leystu \(y\prime=2xy\), með \(y(0)=3\).','Notaðu lausnafjölskylduna úr sýnidæminu.','Við x=0 er eˣ²=1.',r'\(y=3e^{x^2}\). Þá er y′=6xeˣ²=2xy og y(0)=3.','#s2'),
 ex(r'Er \(y\prime=x+y\) þegar á forminu p(x)q(y)?','Skoðaðu hvort hægri hliðin sé summa eða margfeldi.','Ekki má breyta x+y í xy.','Nei. Jafnan er ekki aðskiljanleg á þessu formi. Hana má skrifa sem hliðruðu línulegu jöfnuna y′−y=x.','#s2')]),
 page('Upphafsskilyrði og val á lausnargrein','Nota skilyrði til að velja formerki og finna gilt lausnarbil.',r'''<p>Heildun gefur stundum samband sem þarf að leysa fyrir y. Þá getur sama samband lýst fleiri en einum ferli. Upphafsskilyrðið hjálpar við að velja rétta <strong>lausnargrein</strong>.</p><h3>Sýnidæmi 12.3.1 — neikvætt upphafsgildi</h3>\[y\,y'=x.\]\[y(0)=-2.\]<p>Heildun gefur:</p>\[\frac{y^2}{2}=\frac{x^2}{2}+C.\]<p>Skilyrðið gefur 2=C. Því fæst:</p>\[y^2=x^2+4.\]<p>Við gætum tekið jákvæða eða neikvæða kvaðratrót. Upphafsgildið er neikvætt, svo rétta greinin er:</p>\[y=-\sqrt{x^2+4}.\]<p>Athugun:</p>\[y'=-\frac{x}{\sqrt{x^2+4}}.\]\[y\,y'=x.\]\[y(0)=-2.\]<p>Rótin er aldrei núll. Lausnin er skilgreind og diffranleg fyrir öll raungildi x.</p><h2>Lausnarformúla gildir ekki endilega alls staðar</h2><h3>Sýnidæmi 12.3.2</h3>\[y'=-\frac{x}{y}.\]\[y(0)=2.\]<p>Jafnan er aðeins skilgreind þegar y≠0. Margföldum með y og heildum:</p>\[y\,y'=-x.\]\[\frac{y^2}{2}=-\frac{x^2}{2}+C.\]<p>Skilyrðið gefur C=2. Veljum jákvæða grein:</p>\[y=\sqrt{4-x^2}.\]<p>Lausnin þarf að vera diffranleg og uppfylla upphaflegu jöfnuna. Hér þýðir það að rótin verði að vera jákvæð:</p>\[-2<x<2.\]<p>Á því bili er y&gt;0 og y′=−x/√(4−x²)=−x/y. Við endapunktana verður y=0 og upphaflega jafnan er ekki skilgreind. Því megum við ekki taka endapunktana með, þótt rótin sjálf hafi þar gildi.</p>''',[
 ex(r'Leystu \(y\,y\prime=2x\), með \(y(0)=1\).','Heilda fyrst og notaðu skilyrðið áður en þú velur rót.','y²=2x²+C og C=1.',r'\(y=\sqrt{2x^2+1}\), fyrir öll raungildi x. Þá er y′=2x/√(2x²+1), svo yy′=2x og y(0)=1.','#s3'),
 ex(r'Leystu \(y\,y\prime=x\), með \(y(0)=-3\).','Upphafsgildið velur neikvæða grein.','Heildun og skilyrðið gefa y²=x²+9.',r'\(y=-\sqrt{x^2+9}\), fyrir öll raungildi x. Diffrun gefur yy′=x og y(0)=−3.','#s3'),
 ex(r'Leystu \(y\prime=-x/y\), með \(y(0)=3\), og útskýrðu hvers vegna y má ekki vera núll.','Heilda yy′=−x og notaðu skilyrðið.','y²=9−x². Upphaflega jafnan krefst y≠0.',r'\(y=\sqrt{9-x^2}\), á \(-3<x<3\). Þar er y′=−x/y og y(0)=3.','#s3')]),
 page('Lausnir sem geta tapast við deilingu','Finna fastalausnir og athuga hvar lausnarform er gilt.',r'''<p>Deiling með breytistæðu getur útilokað lausnir. Við þurfum að halda utan um þær sérstaklega.</p><h3>Sýnidæmi 12.4.1</h3>\[y'=xy^2.\]<p>Fyrst athugum við y=0. Bæði y′ og xy² eru þá núll, svo núllfallið er lausn.</p><p>Fyrir y≠0 deilum við með y² og heildum:</p>\[\frac{y'}{y^2}=x.\]\[\int y^{-2}\,dy=\int x\,dx.\]\[-\frac1y=\frac{x^2}{2}+C.\]<p>Einangrum y:</p>\[y=-\frac1{x^2/2+C}.\]<p>Lausnin gildir á bilum þar sem nefnarinn er ekki núll. Hún verður aldrei núll, svo núlllausnin fæst ekki með vali á C í þessari formúlu. Hana þarf að telja sérstaklega.</p><h2>Upphafsskilyrði og núllstöðvar nefnara</h2><p>Ef y(0)=1 fæst −1=C og því:</p>\[y=\frac1{1-x^2/2}.\]<p>Stærsta opna lausnarbilið sem inniheldur 0 er:</p>\[-\sqrt2<x<\sqrt2.\]<p>Á því bili er y′=x/(1−x²/2)²=xy² og y(0)=1. Við endamörkin stefnir lausnin upp án takmarka; ekki má halda henni áfram yfir núllstöð nefnarans.</p><aside>Prófaðu útilokuð föst gildi í upphaflegu jöfnunni. Þau eru ekki alltaf lausnir allra gerða deildajafna. Fyrir y′=p(x)q(y) gefur hver núllstöð q fastalausn, en önnur útilokuð gildi geta komið frá skilgreiningarmengi upphaflegu jöfnunnar.</aside>''',[
 ex(r'Hvaða fastalausnir hefur \(y\prime=x(y-2)\)?','Settu y=b, þar sem b er fasti.','Þá þarf 0=x(b−2) að gilda fyrir öll x á bili.',r'y=2 er eina fastalausnin. Hún tapast ef deilt er með y−2 án þess að athuga hana sérstaklega.','#s4'),
 ex(r'Finndu allar lausnir \(y\prime=y^2\) og tilgreindu hvar formúlan fyrir ófastar lausnir gildir.','Athugaðu y=0 áður en þú deilir með y².','Fyrir y≠0 fæst −1/y=x+C.',r'Núllfallið er lausn. Aðrar lausnir eru \(y=-1/(x+C)\), á bilum sem innihalda ekki x=−C. Diffrun gefur y′=1/(x+C)²=y².','#s4'),
 ex(r'Leystu \(y\prime=xy^2\), með \(y(0)=0\).','Prófaðu upphafsgildið sem fastalausn áður en þú deilir.','Núllfallið hefur afleiðuna núll.',r'y=0 uppfyllir jöfnuna og upphafsskilyrðið fyrir öll x. Lausnirnar sem fást með deilingu með y² geta ekki uppfyllt y(0)=0.','#s4')]),
 page('Hagnýting: hraði og viðnám','Setja upp og leysa aðskiljanlegt líkan og túlka lausnina.',r'''<p>Í einföldu líkani um hreyfingu með viðnámi er minnkunarhraði jákvæðs hraða í hlutfalli við hraðann í öðru veldi. Látum t vera tíma í sekúndum og v(t) hraða í m/s:</p>\[v'=-0{,}1v^2.\]\[v(0)=10.\]<p>Upphafshraðinn er jákvæður. Við leitum að jákvæðri lausn og aðskiljum breyturnar:</p>\[\frac{v'}{v^2}=-0{,}1.\]\[\int v^{-2}\,dv=\int-0{,}1\,dt.\]\[-\frac1v=-0{,}1t+C.\]<p>Upphafsskilyrðið gefur:</p>\[-\frac1{10}=C.\]<p>Því fæst:</p>\[-\frac1v=-0{,}1(t+1).\]\[v(t)=\frac{10}{t+1}.\]<h2>Athugun og túlkun</h2>\[v'(t)=-\frac{10}{(t+1)^2}.\]\[-0{,}1v(t)^2=-\frac{10}{(t+1)^2}.\]\[v(0)=10.\]<p>Lausnin uppfyllir báðar kröfurnar. Fyrir t≥0 er hraðinn jákvæður og minnkar í átt að núlli. Eftir 4 sekúndur er v(4)=2 m/s.</p><p>Stærsta opna stærðfræðilega lausnarbilið sem inniheldur 0 er −1&lt;t&lt;∞. Í viðfangsefninu notum við aðeins t≥0, þar sem t=0 markar upphaf mælingar.</p><h2>Er þetta veldishnignun?</h2><p>Nei. Í einingu 10 var breytingahraði í hlutfalli við v og lausnin vísisfall. Hér er breytingahraðinn í hlutfalli við v² og lausnin rætt fall. Hraðinn er helmingur upphafshraðans við t=1, en helmingur þess hraða, 2,5 m/s, við t=3. Tíminn milli helmingana er því ekki fastur.</p>''',[
 ex(r'Í sama líkani er \(v(0)=5\). Finndu v(t) fyrir t≥0.','Notaðu almenna sambandið −1/v=−0,1t+C.','Skilyrðið gefur C=−1/5.',r'\(v(t)=10/(t+2)\), fyrir t≥0. Þá er v′=−10/(t+2)²=−0,1v² og v(0)=5.','#s5'),
 ex(r'Fyrir \(v(t)=10/(t+1)\), hvenær er hraðinn 1 m/s?','Settu v(t)=1.','10/(t+1)=1 gefur t+1=10.','Við t=9 sekúndur.','#s5'),
 ex(r'Er fastafallið v=0 lausn \(v\prime=-0{,}1v^2\)? Uppfyllir það líka v(0)=10?','Athugaðu jöfnuna og skilyrðið hvort í sínu lagi.','Núllfallið hefur afleiðuna núll.','Það leysir deildajöfnuna, en uppfyllir ekki upphafsskilyrðið v(0)=10.','#s5')]),
 page('Samantekt, orðalisti og formúlur','Tengja aðskilnað, heildun, upphafsskilyrði og lausnarbil.',summary([
 'Aðskilnað má nota þegar breyta má jöfnunni í g(y)y′=f(x).','Heilda skal y-hlið með tilliti til y og x-hlið með tilliti til x.','Einn frjáls heildunarfasti nægir í sambandinu milli stofnfallanna.','Áður en deilt er með stæðu sem inniheldur y þarf að athuga útilokuð gildi.','Upphafsskilyrði getur ákvarðað bæði fastann og rétta lausnargrein.','Athuga þarf upprunalegu jöfnuna, skilyrðin og hvar lausnin er skilgreind og diffranleg.'
 ],[
 ('<a href="#s1">Aðskiljanleg deildajafna</a> <span lang="en">(separable differential equation)</span>','Jafna sem má færa á form þar sem x og y eru aðskildar við heildun.'),
 ('<a href="#s1">Óbein framsetning lausnar</a> <span lang="en">(implicit solution)</span>','Samband milli x og y þar sem y hefur ekki endilega verið einangrað.'),
 ('<a href="#s3">Lausnargrein</a> <span lang="en">(solution branch)</span>','Eitt af þeim föllum sem samband milli x og y getur lýst.'),
 ('<a href="#s3">Lausnarbil</a> <span lang="en">(interval of solution)</span>','Bil þar sem fallið er skilgreint, diffranlegt og uppfyllir deildajöfnuna.'),
 ('<a href="#s4">Fastalausn</a> <span lang="en">(constant solution)</span>','Fastafall sem uppfyllir deildajöfnuna; einnig nefnt jafnvægislausn.')
 ],r'''<p><strong>Aðskilnaður breyta og heildun</strong></p>\[g(y)y'=f(x).\]\[G(y)=F(x)+C.\]<p>Hér er G′=g og F′=f. Sambandið þarf að lýsa diffranlegu falli y á viðkomandi bili.</p><p><strong>Aðskilnaður úr margfeldisformi</strong></p>\[y'=p(x)q(y).\]\[\int\frac1{q(y)}\,dy=\int p(x)\,dx.\]<p>Deilingarskrefið gildir þar sem q(y)≠0. Ef q(b)=0 er y=b fastalausn sem þarf að taka með sérstaklega.</p><p><strong>Athugun með keðjureglu</strong></p>\[\frac{d}{dx}G(y(x))=G'(y)y'.\]<p>Notaðu upphaflegu jöfnuna til að staðfesta lausnina. Taktu ekki með punkta þar sem hún eða lausnin er óskilgreind.</p>''')+r'''<h2>Algeng mistök</h2><ul><li>Að heilda fall af y með tilliti til x án þess að taka y′ með.</li><li>Að aðskilja summu x+y eins og hún væri margfeldi xy.</li><li>Að týna núlllausn eða annarri fastalausn við deilingu.</li><li>Að gleyma algildismerkjum í heildi 1/y.</li><li>Að velja jákvæða rót þótt upphafsgildið sé neikvætt.</li><li>Að taka núllstöð nefnara með í lausnarbilið.</li></ul><h2>Athugaðu skilninginn</h2><ul><li>Geturðu bent á hvað fer aðeins eftir x og hvað aðeins eftir y?</li><li>Geturðu fundið lausnir sem deiling gæti útilokað?</li><li>Geturðu rökstutt lausnargrein og lausnarbil út frá upphaflegu jöfnunni?</li></ul>'''),
 page('Blandað dæmasafn','Velja aðferð og setja fram lausn ásamt viðeigandi skilyrðum.','',[
 ex(r'Leystu \((1+y^2)y\prime=3x^2\), með \(y(0)=0\). Gefðu óbeint samband milli x og y.','Heilda með tilliti til réttrar breytu hvorum megin.','y+y³/3=x³+C. Skilyrðið gefur C=0.',r'\(y+y^3/3=x^3\). Diffrun gefur (1+y²)y′=3x² og sambandið gefur y=0 við x=0. Þar sem 1+y² er alltaf jákvætt lýsir sambandið einu diffranlegu falli y fyrir öll x.','#s1'),
 ex(r'Leystu \(y\prime=xy\), með \(y(0)=2\).','Athugaðu núlllausnina og aðskildu síðan fyrir y≠0.','ln|y|=x²/2+C.',r'\(y=2e^{x^2/2}\), fyrir öll x. Þá er y′=xy og y(0)=2.','#s2'),
 ex(r'Finndu allar lausnir \(y\prime=2y^2\).','Athugaðu fastalausn áður en þú deilir.','Fyrir y≠0 gefur heildun −1/y=2x+C.',r'y=0 er lausn. Aðrar lausnir eru \(y=-1/(2x+C)\), á bilum þar sem 2x+C≠0. Diffrun gefur y′=2y².','#s4'),
 ex(r'Leystu \(y\prime=-x/y\), með \(y(0)=-1\), og gefðu lausnarbilið sem inniheldur 0.','Upphafsgildið velur neikvæða grein.','y²=1−x² og y má ekki vera núll.',r'\(y=-\sqrt{1-x^2}\), á \(-1<x<1\). Afleiðan er x/√(1−x²)=−x/y og y(0)=−1.','#s3'),
 ex(r'Nemandi deilir \(y\prime=x(y-1)\) með y−1 og segir síðan að y=1 geti ekki verið lausn. Er það rétt?','Athugaðu fallið í upphaflegu jöfnunni.','Afleiða y=1 er núll.','Nei. y=1 er fastalausn, því 0=x(1−1). Deiling með y−1 útilokar hana aðeins úr því lausnarskrefi.','#s4'),
 ex(r'Leystu \(y\prime+2y=0\), með \(y(0)=3\). Má nota fleiri en eina leið?','Þetta er bæði óhliðruð línuleg jafna og aðskiljanleg jafna.','Notaðu þekkta vísislausn eða heilda y′/y=−2 fyrir y≠0.',r'\(y=3e^{-2x}\). Báðar leiðir gefa sama svar. Þá er y′+2y=0 og y(0)=3.','unit-10.html#s3'),
 ex(r'Leystu \(y\prime+y=x\), með \(y(0)=0\).','Þetta er hliðruð línuleg jafna. Aðskilnaður x og y er ekki bein leið hér.','Prófaðu yₚ=Ax+B. Þá fæst yₚ=x−1.',r'\(y=x-1+e^{-x}\). Þá er y′+y=x og y(0)=0.','unit-11.html#s3')])])

def choice_widget():
 return '''<div class="formula" id="separable-practice"><h2>Er jafnan aðskiljanleg?</h2><div data-separable-cards></div></div>'''
